#include <iostream>
#include <vector>
#include <stdexcept>
int main() {
  std::vector<int> vec = {1, 2, 3};
  try {
    int x = vec.at(10); // Accessing beyond bounds
    std::cout << x << std::endl;
  } catch (const std::out_of_range& oor) {
    std::cerr << "Out of Range error: " << oor.what() << std::endl;
    // Even here, the state of other STL containers might be unpredictable
  }
  return 0;
}
